import type { NextApiRequest, NextApiResponse } from "next";

// middleware.ts adds its own challenges to this route. A Next.js Pages API
// handler writes to the response that already holds middleware's headers, so
// its challenge replaces middleware's instead of joining it.
export default function handler(_request: NextApiRequest, response: NextApiResponse) {
  response.setHeader("WWW-Authenticate", 'Bearer realm="handler"');
  response.status(401).end("Unauthorized");
}

// middleware.ts adds its own challenges (and a singular x-auth-source header)
// to this route. As in Next.js, the handler's WWW-Authenticate and
// Proxy-Authenticate values are kept after middleware's, while middleware still
// owns singular headers.
export function GET() {
  return new Response("Unauthorized", {
    status: 401,
    headers: {
      "WWW-Authenticate": 'Bearer realm="handler"',
      "Proxy-Authenticate": 'Bearer realm="handler"',
      "x-auth-source": "handler",
    },
  });
}

